func wait(_ t: Double = 20, _ f: () -> Bool) -> Bool { let e = Date().addingTimeInterval(t); while Date() < e { if f() { return true }; RunLoop.main.run(until: Date().addingTimeInterval(0.03)) }; return f() }
func put(_ p: String, _ s: String = "x") -> URL { let u = root.appendingPathComponent(p); try! fm.createDirectory(at: u.deletingLastPathComponent(), withIntermediateDirectories: true); try! s.write(to: u, atomically: true, encoding: .utf8); return u }
func game(_ m: Model, _ id: String) -> Game? { m.games.first { $0.titleID == id } }
func id(_ n: Int) -> String { String(format: "0100%08X000", n + 16) + "0" }
func nsp(_ n: Int, _ mode: String = "ok") -> URL { put("dump/Game \(n) [\(id(n))][v0].nsp", mode) }
func log() -> [String] { ((try? String(contentsOf: root.appendingPathComponent("engine.log"), encoding: .utf8)) ?? "").split(separator: "\n").map(String.init) }
